import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';

/**
 * Private object storage for sensitive documents (registration, verification, transfer).
 * The approved production target is Cloudflare R2 (private bucket); its implementation is a
 * later integration and must implement this interface. Objects are addressed by random keys
 * generated by the server, never by user input, and are never publicly reachable.
 */
export interface PrivateObjectStorage {
  readonly name: string;
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
}

export class ProductionLocalStorageError extends Error {
  constructor() {
    super('Local private storage must never be used in production');
  }
}

const KEY_PATTERN = /^private\/[a-z-]+\/[0-9a-f]{32}$/;

/**
 * DEVELOPMENT/TEST ONLY: stores objects on the local disk (mode 0600). Refused in production by
 * config validation and by this constructor.
 */
export class LocalPrivateStorage implements PrivateObjectStorage {
  readonly name = 'local';
  private readonly root: string;

  constructor(root: string, nodeEnv: string) {
    if (nodeEnv === 'production') throw new ProductionLocalStorageError();
    this.root = resolve(root);
  }

  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(join(path, '..'), { recursive: true, mode: 0o700 });
    await writeFile(path, data, { mode: 0o600, flag: 'wx' });
  }

  async get(key: string): Promise<Buffer> {
    return readFile(this.pathFor(key));
  }

  private pathFor(key: string): string {
    if (!KEY_PATTERN.test(key)) throw new Error('Invalid storage key');
    return join(this.root, key);
  }
}
